def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(f"5! = {factorial(5)}")

def sum_n(n):
    if n <= 1:
        return n
    return n + sum_n(n - 1)

print(f"Sum 1 to 10 = {sum_n(10)}")

def check_even_odd(number):
    return 'Even' if number % 2 == 0 else 'Odd'

print(f"27 is {check_even_odd(27)}")

def largest(a, b, c):
    if a >= b and a >= c:
        return a
    elif b >= a and b >= c:
        return b
    return c

print(f"Largest: {largest(45, 89, 23)}")
